"""Plugin registry. Plugins are registered by name with a factory, looked up with get,
built with create, and dropped with unregister.
"""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

Factory = Callable[..., Any]


class Registry:
    """Plugin names mapped to factories, in registration order."""

    def __init__(self) -> None:
        self._plugins: dict[str, Factory] = {}

    def register(self, name: str, factory: Factory) -> None:
        """Add a plugin; names must be unique."""
        if name in self._plugins:
            raise ValueError(f"plugin {name!r} is already registered")
        self._plugins[name] = factory

    def unregister(self, name: str) -> None:
        """Remove a plugin by name; ValueError if unknown."""
        if name not in self._plugins:
            raise ValueError(f"plugin {name!r} is not registered")
        del self._plugins[name]

    def remove(self, name: str) -> None:
        """Remove a plugin by name (the same as unregister)."""
        self.unregister(name)

    def get(self, name: str) -> Factory:
        """The factory registered under name; KeyError if unknown."""
        return self._plugins[name]

    def find(self, name: str, default: Factory | None = None) -> Factory | None:
        """The factory registered under name, or default if unknown."""
        return self._plugins.get(name, default)

    def names(self) -> list[str]:
        """Registered plugin names in registration order."""
        return list(self._plugins)

    def create(self, name: str, *args: Any, **kwargs: Any) -> Any:
        """Build a plugin instance by calling its factory."""
        return self.get(name)(*args, **kwargs)

